const EN_L = {
  today: 'Today', yesterday: 'Yesterday', week: 'This week', month: 'This month', multi: 'Several sites', noTg: 'No tab group', untitledTg: '(untitled)',
  noCat: 'Uncategorised', now: 'Now', locale: 'en-US', pinned: 'Pinned',
  everyWd: (w) => `Every ${w}`, everyWdHour: (w, h) => `Every ${w} ${String(h).padStart(2, '0')}:00–${String(h).padStart(2, '0')}:59`,
  everyHour: (h) => `Every day ${String(h).padStart(2, '0')}:00–${String(h).padStart(2, '0')}:59`, everyDom: (d) => `Day ${d} of the month`,
  parts: ['Morning (05–11)', 'Afternoon (12–16)', 'Evening (17–20)', 'Night (21–04)'], weekdays: ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'],
  ageBuckets: ['Under 1 day', '1–7 days', '7–30 days', '30–90 days', 'Over 90 days', 'Unknown'],
  countRanges: ['1 tab', '2–5 tabs', '6–20 tabs', '21–100 tabs', '101–500 tabs', 'More than 500 tabs'],
};

let thSnap = null;
let thL = null;

export function resolveLang(pref) {
  if (pref === 'th' || pref === 'en') return pref;
  let ui = '';
  try { ui = (chrome.i18n.getUILanguage() || navigator.language || '').toLowerCase(); } catch { ui = (navigator.language || '').toLowerCase(); }
  return ui.startsWith('th') ? 'th' : 'en';
}

/** Overlays English on the (Thai) STR object, or restores Thai. Returns the language in use. */
export function applyLanguage(STR, L, pref) {
  if (!thSnap) { thSnap = { ...STR }; thL = { ...L }; }
  const lang = resolveLang(pref);
  Object.assign(STR, thSnap);
  Object.assign(L, thL);
  if (lang === 'en') { Object.assign(STR, EN); Object.assign(L, EN_L); }
  try { document.documentElement.lang = lang; } catch { /* ignore */ }
  return lang;
}

